<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';require_once __DIR__.'/../app/business_microsite_v1130.php';$u=current_user();if(!$u||!(has_permission('businesses.manage',$u)||has_permission('settings.manage',$u))){http_response_code(403);exit('Forbidden');}$uid=(int)$u['id'];$bid=(int)($_REQUEST['business_id']??0);$rows=sk1130_businesses('',200);if($bid<1&&$rows)$bid=(int)$rows[0]['id'];$b=$bid?sk1130_business($bid):null;$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&$b){csrf_check();$a=(string)($_POST['action']??'save');if($a==='save'){sk1170_save_builder($bid,$_POST,$uid);$msg='Website builder settings saved.';}elseif($a==='lead') {sk1170_update_lead((int)($_POST['lead_id']??0),$bid,(string)($_POST['status']??'new'),(string)($_POST['owner_note']??''));$msg='Lead updated.';}}}catch(Throwable $e){$err=$e->getMessage();}$cfg=$b?sk1170_builder($bid):[];$stats=$b?sk1170_lead_stats($bid):[];$leads=$b?sk1170_leads($bid,100):[];page_start('Business Website Builder',true);?><link rel="stylesheet" href="/assets/business-builder-v1170.css?v=1170"><div class="bb1170"><section class="hero"><div><span>SHAHKOTPK v11.7</span><h1>Business Website Builder</h1><p>Control the full website slider, sections, calls-to-action and customer enquiries without changing the business record.</p></div><?php if($b):?><a href="/business-site.php?id=<?=$bid?>" target="_blank">Preview Website ↗</a><?php endif;?></section><?php if($msg):?><div class="notice ok"><?=sk1130_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1130_h($err)?></div><?php endif;?><section class="panel"><form method="get" class="chooser"><label>Business<select name="business_id" onchange="this.form.submit()"><?php foreach($rows as $x):?><option value="<?=(int)$x['id']?>" <?=(int)$x['id']===$bid?'selected':''?>><?=sk1130_h((string)sk1130_business_value($x,['name'],'Business'))?></option><?php endforeach;?></select></label></form><?php if($b):?><div class="metrics"><article><b><?=number_format((int)($stats['views']??0))?></b><span>30d views</span></article><article><b><?=number_format((int)($stats['total']??0))?></b><span>30d leads</span></article><article><b><?=number_format((int)($stats['new']??0))?></b><span>new leads</span></article><article><b><?=number_format((float)($stats['conversion']??0),1)?>%</b><span>lead conversion</span></article></div><form method="post" class="builder"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="save"><div class="grid"><section><h2>Hero slider</h2><label>Custom headline<input name="hero_title" value="<?=sk1130_h($cfg['hero_title']??'')?>" placeholder="Leave blank for automatic business title"></label><label>Custom subtitle<textarea name="hero_subtitle" rows="3"><?=sk1130_h($cfg['hero_subtitle']??'')?></textarea></label><div class="two"><label>CTA label<input name="hero_cta_label" value="<?=sk1130_h($cfg['hero_cta_label']??'')?>"></label><label>CTA URL<input name="hero_cta_url" value="<?=sk1130_h($cfg['hero_cta_url']??'')?>" placeholder="#contact"></label></div><label class="toggle"><input type="checkbox" name="slider_autoplay" value="1" <?=!empty($cfg['slider_autoplay'])?'checked':''?>> Autoplay slider</label><label>Slider speed (ms)<input type="number" min="3000" max="15000" step="500" name="slider_speed_ms" value="<?=(int)($cfg['slider_speed_ms']??6500)?>"></label></section><section><h2>Website actions</h2><?php foreach([['lead_form_enabled','Customer enquiry form'],['show_phone','Call button'],['show_whatsapp','WhatsApp button'],['show_directions','Directions button'],['show_booking','Booking / enquiry button']] as [$k,$lab]):?><label class="toggle"><input type="checkbox" name="<?=$k?>" value="1" <?=!empty($cfg[$k])?'checked':''?>> <?=$lab?></label><?php endforeach;?></section><section class="wide"><h2>Sections</h2><p>Set order numbers and hide anything you do not want on this business website.</p><div class="section-grid"><?php $order=(array)($cfg['section_order']??[]);$hidden=(array)($cfg['hidden_sections']??[]);foreach(['about'=>'About','services'=>'Services','products'=>'Products','gallery'=>'Gallery','offers'=>'Offers','reviews'=>'Reviews','faq'=>'FAQ','contact'=>'Contact'] as $k=>$lab):$pos=array_search($k,$order,true);?><div><b><?=$lab?></b><input type="number" min="1" max="20" data-order-key="<?=$k?>" value="<?=$pos===false?9:$pos+1?>"><label><input type="checkbox" name="hidden_sections[]" value="<?=$k?>" <?=in_array($k,$hidden,true)?'checked':''?>> Hide</label></div><?php endforeach;?></div><div data-order-hidden></div></section></div><button class="save">Save Website Builder</button></form><script>document.querySelector('.builder')?.addEventListener('submit',e=>{document.querySelectorAll('[data-order-hidden] input').forEach(x=>x.remove());const box=document.querySelector('[data-order-hidden]');[...document.querySelectorAll('[data-order-key]')].sort((a,b)=>+a.value-+b.value).forEach(i=>{const x=document.createElement('input');x.type='hidden';x.name='section_order[]';x.value=i.dataset.orderKey;box.appendChild(x)})})</script><?php endif;?></section><?php if($b):?><section class="panel"><div class="head"><div><span>LEADS</span><h2>Customer enquiries</h2></div></div><div class="lead-list"><?php foreach($leads as $l):?><article><div><small><?=sk1130_h((string)$l['created_at'])?></small><h3><?=sk1130_h((string)$l['customer_name'])?></h3><p><?=sk1130_h((string)$l['subject'])?></p><p><?=nl2br(sk1130_h((string)$l['message']))?></p><div class="contact"><?php if($l['phone']):?><a href="tel:<?=sk1130_h((string)$l['phone'])?>"><?=sk1130_h((string)$l['phone'])?></a><?php endif;?><?php if($l['email']):?><a href="mailto:<?=sk1130_h((string)$l['email'])?>"><?=sk1130_h((string)$l['email'])?></a><?php endif;?></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="lead"><input type="hidden" name="lead_id" value="<?=(int)$l['id']?>"><select name="status"><?php foreach(['new','contacted','qualified','won','closed'] as $st):?><option <?=$l['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><textarea name="owner_note" placeholder="Internal note"><?=sk1130_h((string)($l['owner_note']??''))?></textarea><button>Update</button></form></article><?php endforeach;?><?php if(!$leads):?><p class="empty">No website leads yet.</p><?php endif;?></div></section><?php endif;?></div><?php require __DIR__.'/../app/end.php';?>
